(()=>{'use strict';const data=window.CTComponents,$=s=>document.querySelector(s),cats=[...new Set(data.map(p=>p.category))];const viCats={"Fixed-Wing Motor":"Động cơ cánh cố định","Multirotor Motor":"Động cơ đa cánh quạt","Propeller":"Cánh quạt","ESC":"ESC","Flight Controller":"Bộ điều khiển bay","GNSS & Positioning":"GNSS & định vị","Power Modules & PDB":"Mô-đun nguồn & PDB","Transmission & Telemetry":"Truyền dẫn & đo từ xa","Cylindrical":"Cell hình trụ","Gimbal Camera":"Camera gimbal","HVLi Pouch":"Pin túi HVLi","Intelligent Battery":"Pin thông minh","LiPo Pouch":"Pin túi LiPo","Semi-Solid Cell":"Cell bán rắn","Semi-Solid HV Pack":"Bộ pin bán rắn cao áp","Semi-Solid Pack":"Bộ pin bán rắn","Smart BMS":"BMS thông minh","Smart Charger":"Bộ sạc thông minh","Ground Controller":"Bộ điều khiển mặt đất","Rescue & Firefighting":"Cứu hộ & chữa cháy","EO-IR":"EO-IR","Gimbal & Mount":"Gimbal & giá đỡ","Payload Delivery":"Thiết bị thả hàng"};const productNames={"ESC":["Electronic Speed Controller","Bộ điều tốc điện tử (ESC)"],"Propeller":["Propeller","Cánh quạt"],"Multirotor Motor":["Multirotor Motor","Động cơ đa cánh quạt"],"Fixed-Wing Motor":["Fixed-Wing Motor","Động cơ cánh cố định"],"Cylindrical":["Cylindrical Battery Cell","Cell pin hình trụ"],"Intelligent Battery":["Intelligent Battery","Pin thông minh"],"Semi-Solid Cell":["Semi-Solid Battery Cell","Cell pin bán rắn"],"Ground Controller":["Ground Controller","Bộ điều khiển mặt đất"],"EO-IR":["EO-IR Camera","Camera EO-IR"],"Gimbal Camera":["Gimbal Camera","Camera gimbal"]};const pname=p=>{const n=productNames[p.category];return n?tx(n[0],n[1]):p.category};const pnameEn=p=>(productNames[p.category]||[p.category])[0];let lang=localStorage.getItem('ct-components-lang')==='vi'?'vi':'en',category=new URLSearchParams(location.search).get('category')||sessionStorage.getItem('ctuav-component-category')||'All';if(!cats.includes(category))category='All';const tx=(en,vi)=>lang==='vi'?vi:en;const label=c=>lang==='vi'?(viCats[c]||c):c;let pageNumber=1,lastFilterKey='';const pageSize=10;const grid=$('#grid');function animateCards(){if(!grid||matchMedia('(prefers-reduced-motion: reduce)').matches)return;[...grid.children].forEach((card,i)=>card.animate([{transform:'translateY(16px)'},{transform:'translateY(0)'}],{duration:1100,delay:Math.min(i,5)*70,easing:'cubic-bezier(.16,1,.3,1)'}))}const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));addEventListener('message',e=>{if(e.source===parent&&e.data?.namespace==='ctuav-demo'&&e.data.type==='view-active'&&e.data.active&&grid){const saved=sessionStorage.getItem('ctuav-component-category');if(saved&&cats.includes(saved)){category=saved;sessionStorage.removeItem('ctuav-component-category');render()}}});function render(){if(!grid)return;$('#categories').innerHTML=['All',...cats].map(c=>`<button type="button" class="news-filter" data-cat="${c}" aria-pressed="${category===c}">${c==='All'?tx('All components','Tất cả'):label(c)}<span>${c==='All'?data.length:data.filter(p=>p.category===c).length}</span></button>`).join('');const mobile=$('#categorySelect');if(mobile){mobile.innerHTML=['All',...cats].map(c=>`<option value="${esc(c)}"${category===c?' selected':''}>${c==='All'?tx('All components','Tất cả linh kiện'):label(c)} (${c==='All'?data.length:data.filter(p=>p.category===c).length})</option>`).join('')}const q=$('#search').value.trim().toLocaleLowerCase();let list=data.filter(p=>(category==='All'||category===p.category)&&(!q||`${p.name} ${p.category} ${viCats[p.category]} ${(productNames[p.category]||[]).join(' ')}`.toLocaleLowerCase().includes(q)));if($('#sort').value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if($('#sort').value==='za')list.sort((a,b)=>b.name.localeCompare(a.name));$('#count').textContent=tx(`${list.length} of ${data.length} components`,`${list.length} / ${data.length} linh kiện`);const filterKey=JSON.stringify([category,q,$('#sort').value]);if(filterKey!==lastFilterKey){pageNumber=1;lastFilterKey=filterKey}const pages=Math.max(1,Math.ceil(list.length/pageSize));pageNumber=Math.min(pageNumber,pages);const start=(pageNumber-1)*pageSize;$('#count').textContent=list.length?tx(`${start+1}–${Math.min(start+pageSize,list.length)} of ${list.length} components`,`${start+1}–${Math.min(start+pageSize,list.length)} / ${list.length} linh kiện`):tx('0 components','0 linh kiện');const pager=$('#componentPagination');if(pager){pager.setAttribute('aria-label',tx('Component pages','C\u00e1c trang linh ki\u1ec7n'));pager.hidden=list.length<=pageSize;pager.innerHTML=`<button type="button" data-page-number="${pageNumber-1}" ${pageNumber===1?'disabled':''} aria-label="${tx('Previous page','Trang trước')}">←</button>`+Array.from({length:pages},(_,i)=>`<button type="button" data-page-number="${i+1}" ${i+1===pageNumber?'aria-current="page"':''} aria-label="${tx('Page','Trang')} ${i+1}">${i+1}</button>`).join('')+`<button type="button" data-page-number="${pageNumber+1}" ${pageNumber===pages?'disabled':''} aria-label="${tx('Next page','Trang sau')}">→</button>`}$('#empty').hidden=list.length>0;grid.innerHTML=list.slice(start,start+pageSize).map(p=>{const url=p.detail?'component-'+p.id+'.html':'#image-'+p.id;return`<article class="card"><a class="card-link" href="${url}" ${p.detail?'':`data-preview="${p.id}"`} aria-label="${esc(pname(p))} ${esc(p.name)} — ${p.detail?tx('View details','Xem chi tiết'):tx('View image','Xem ảnh')}"><span class="card-image"><img src="${p.images[0]}" alt="${esc(p.name)}" width="1200" height="900" loading="lazy" decoding="async"></span><h2 class="component-card-name"><span class="component-card-product">${esc(pname(p))}</span><span class="component-card-code">${esc(p.name)}</span></h2></a>${["10020","abc-ss-12s30"].includes(p.id)?`<p class="component-source-status" data-i18n-skip="">Source status: ${esc(p.specs.find(row=>row[0]==='Status')[1])}</p>`:""}<div class="component-card-actions"><button class="cart-add" data-cart-add="" data-cart-id="component:${p.id}" data-cart-name="${esc(pnameEn(p)+' '+p.name)}" data-i18n-skip="" type="button"><svg class="cart-icon" aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M3 4h2.2l2.3 10.2a1.6 1.6 0 0 0 1.6 1.3h8.6a1.6 1.6 0 0 0 1.6-1.2L21 8H6.4" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="9.5" cy="19.6" r="1.5" fill="currentColor"/><circle cx="17.3" cy="19.6" r="1.5" fill="currentColor"/></svg><span data-cart-label="">${tx('Add to Cart','Thêm vào giỏ hàng')}</span></button></div></article>`}).join('');animateCards()}
function language(l){lang=l;document.documentElement.lang=lang;localStorage.setItem('ct-components-lang',lang);document.querySelectorAll('[data-en]').forEach(e=>e.textContent=e.dataset[lang]);document.querySelectorAll('[data-aria-vi]').forEach(e=>{if(!e.dataset.ariaEn)e.dataset.ariaEn=e.getAttribute('aria-label');e.setAttribute('aria-label',lang==='vi'?e.dataset.ariaVi:e.dataset.ariaEn);});{const q=$('#search');if(q)q.placeholder=lang==='vi'?'Tìm theo tên mẫu':'Search by model name';}document.querySelectorAll('[data-category]').forEach(e=>e.textContent=label(e.dataset.category));$('#en').setAttribute('aria-pressed',lang==='en');$('#vi').setAttribute('aria-pressed',lang==='vi');if($('#search')){$('#search').placeholder=tx('Search by model name','Tìm theo tên mẫu');const opts=$('#sort').options;[tx('Category order','Theo danh mục'),tx('Name: A–Z','Tên: A–Z'),tx('Name: Z–A','Tên: Z–A')].forEach((t,i)=>opts[i].textContent=t)}render()}
$('#en').addEventListener('click',()=>language('en'));$('#vi').addEventListener('click',()=>language('vi'));if(grid){$('#componentPagination')?.addEventListener('click',e=>{const b=e.target.closest('[data-page-number]');if(!b||b.disabled)return;pageNumber=Number(b.dataset.pageNumber);render();$('#count').focus({preventScroll:true});$('#count').scrollIntoView({block:'start',behavior:'instant'})});$('#categorySelect')?.addEventListener('change',e=>{category=e.target.value;const u=new URL(location);category==='All'?u.searchParams.delete('category'):u.searchParams.set('category',category);if(parent===window)history.replaceState(null,'',u);render()});$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-cat]');if(!b)return;category=b.dataset.cat;const u=new URL(location);category==='All'?u.searchParams.delete('category'):u.searchParams.set('category',category);if(parent===window)history.replaceState(null,'',u);render();$('#categories').querySelector(`[data-cat="${category}"]`).focus()});$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);$('#reset').addEventListener('click',()=>{category='All';$('#search').value='';$('#sort').value='source';if(parent===window)history.replaceState(null,'',location.pathname);render()})}
if(grid){const preview=$('#catalogue-image-dialog');grid.addEventListener('click',e=>{const a=e.target.closest('[data-preview]');if(!a)return;e.preventDefault();const p=data.find(x=>x.id===a.dataset.preview);$('#preview-name').textContent=p.name;$('#preview-image').src=p.images[0];$('#preview-image').alt=p.name;preview.showModal()});$('#close-preview').addEventListener('click',()=>preview.close());preview.addEventListener('click',e=>{if(e.target===preview)preview.close()})}
const dialog=$('#image-dialog');if(dialog){document.querySelectorAll('.thumb').forEach(b=>b.addEventListener('click',()=>{$('#product-image').src=b.dataset.src;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#product-image').animate([{opacity:.85,transform:'scale(.985)'},{opacity:1,transform:'none'}],{duration:700,easing:'ease-out'});document.querySelectorAll('.thumb').forEach(x=>x.setAttribute('aria-pressed',x===b))}));$('#zoom').addEventListener('click',()=>{$('#enlarged').src=$('#product-image').src;dialog.showModal()});$('#close-image').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}language(lang);const reduce=matchMedia('(prefers-reduced-motion: reduce)');const entranceNodes=document.querySelectorAll('.intro,.detail-hero,.information,.contact-panel');const seen=new WeakSet();const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting||seen.has(e.target))return;seen.add(e.target);observer.unobserve(e.target);if(!reduce.matches)e.target.animate([{transform:'translateY(24px)'},{transform:'translateY(0)'}],{duration:1800,easing:'cubic-bezier(.16,1,.3,1)'});}),{threshold:.08});entranceNodes.forEach(n=>observer.observe(n));const sections=[...document.querySelectorAll('.information[id]')];const sectionObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('.section-nav a').forEach(a=>a.classList.toggle('is-current',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -55% 0px',threshold:0});sections.forEach(n=>sectionObserver.observe(n));reduce.addEventListener('change',()=>{if(reduce.matches)document.getAnimations().forEach(a=>a.finish())});})();